    this.lines = new LineRenderer(gl);
    this.lines.res = [w, h];
    this.mesh = program(gl, MESH_VS, MESH_FS, 'mesh');
    this.meshVao = gl.createVertexArray();
    this.meshBuf = gl.createBuffer();
    gl.bindVertexArray(this.meshVao);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.meshBuf);
    gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 28, 0);
    gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 4, gl.FLOAT, false, 28, 12);
    gl.bindVertexArray(null);

    this.pDown = program(gl, FS_VS, DOWN_FS, 'down');
    this.pUp = program(gl, FS_VS, UP_FS, 'up');
    this.pCopy = program(gl, FS_VS, COPY_FS, 'copy');
    this.pMix = program(gl, FS_VS, MIX_FS, 'mix');
    this.pFinal = program(gl, FS_VS, FINAL_FS, 'final');

    const f = { depth: true };
    this.rtScene = target(gl, w, h, f);
    this.rtA = target(gl, w, h, f);
    this.rtB = target(gl, w, h, f);
    this.rtAccum = target(gl, w, h);
    this.rtMask = target(gl, w, h, { depth: true });
    this.rtOut = target(gl, w, h, { internal: gl.RGBA8, type: gl.UNSIGNED_BYTE, filter: gl.NEAREST });
    this.bloom = [];
    let bw = w >> 1, bh = h >> 1;
    for (let i = 0; i < 7; i++) { this.bloom.push(target(gl, Math.max(2, bw), Math.max(2, bh))); bw >>= 1; bh >>= 1; }
    this.fxCache = {};
  }

  // Custom full-screen shader (backgrounds, fluids, etc.), compiled once per source.
  fx(name, fs, uniforms, { blend = 'add' } = {}) {
    const gl = this.gl;
    if (!this.fxCache[name]) this.fxCache[name] = program(gl, FS_VS, fs, name);
    use(this.fxCache[name], uniforms);
    if (blend === 'add') { gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE); }
    else if (blend === 'alpha') { gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA); }
    else if (blend === 'mul') { gl.enable(gl.BLEND); gl.blendFunc(gl.DST_COLOR, gl.ZERO); }
    else gl.disable(gl.BLEND);
    gl.disable(gl.DEPTH_TEST);
    fullscreen(gl);
    gl.disable(gl.BLEND);
  }

  drawMesh(verts, count, cam, { gain = 1, depthWrite = true, depthTest = true, blend = 'none', offset = 0, fog = [0, 0, 0], fogNear = 1e9, fogFar = 2e9 } = {}) {
    if (!count) return;
    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.meshBuf);
    gl.bufferData(gl.ARRAY_BUFFER, verts.subarray(0, count * 7), gl.DYNAMIC_DRAW);
    use(this.mesh, { uView: cam ? cam.view : ID, uProj: cam ? cam.proj : ID, uScreen: cam ? 0 : 1, uGain: gain, uFog: fog, uFogNear: fogNear, uFogFar: fogFar });
    if (depthTest) { gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL); } else gl.disable(gl.DEPTH_TEST);
    gl.depthMask(depthWrite);
    if (offset) { gl.enable(gl.POLYGON_OFFSET_FILL); gl.polygonOffset(offset, offset); }
    if (blend === 'add') { gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE); }
    else if (blend === 'alpha') { gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA); }
    else gl.disable(gl.BLEND);
    gl.bindVertexArray(this.meshVao);
    gl.drawArrays(gl.TRIANGLES, 0, count);
    gl.bindVertexArray(null);
    gl.disable(gl.POLYGON_OFFSET_FILL);
    gl.disable(gl.BLEND);
    gl.disable(gl.DEPTH_TEST);
    gl.depthMask(true);
  }

