  bindTarget(rt) { bind(this.gl, rt); }
  clearTarget(rt, c = [0, 0, 0]) { bind(this.gl, rt); clear(this.gl, c[0], c[1], c[2], 1); }

  mix(rtA, rtB, rtOut, mode, t, { center = [0.5, 0.5], mask = null } = {}) {
    bind(this.gl, rtOut);
    this.fx('__mix', MIX_FS, {}, { blend: 'none' });
    use(this.pMix, { uA: rtA.tex, uB: rtB.tex, uM: mask ? mask.tex : rtA.tex, uUseMask: mask ? 1 : 0, uMode: mode, uT: t, uAspect: this.w / this.h, uCenter: center, uRes: [this.w, this.h] });
