    fullscreen(this.gl);
  }

  copy(src, dst, gain = 1, add = false) {
    const gl = this.gl;
    bind(gl, dst);
    use(this.pCopy, { uTex: src.tex, uGain: gain });
    if (add) { gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE); } else gl.disable(gl.BLEND);
