const MESH_VS = `#version 300 es
precision highp float;
layout(location=0) in vec3 aP;
layout(location=1) in vec4 aC;
uniform mat4 uView, uProj;
uniform float uScreen;
uniform vec2 uRes;
out vec4 vC;
out float vD;
