  vD = -v.z;
  gl_Position = uProj * v;
}`;
const MESH_FS = `#version 300 es
precision highp float;
in vec4 vC; in float vD;
uniform float uGain, uFogNear, uFogFar;
uniform vec3 uFog;
out vec4 o;
void main(){
  float f = clamp((vD - uFogNear) / max(1e-3, uFogFar - uFogNear), 0., 1.);
  o = vec4(mix(vC.rgb * uGain, uFog, f), vC.a);
