import { createGL } from './gl.js';
import { Renderer } from './renderer.js';
import { Audio } from './audio.js';
import { Director } from './director.js';

const params = new URLSearchParams(location.search);
const SCALE = parseFloat(params.get('scale') || '1');
const W = Math.round(1920 * SCALE), H = Math.round(1080 * SCALE);

const canvas = document.getElementById('c');
canvas.width = W; canvas.height = H;
const gl = createGL(canvas);
const R = new Renderer(gl, W, H);
const A = await new Audio().load('data/');
const D = new Director(R, A);
const px = new Uint8Array(W * H * 4);

function renderFrame(f, { subframes = 1, shutter = 0.5 } = {}) {
  const t = f / 60;
  D.prepare(f);
  let src;
  if (subframes <= 1) {
    D.render(t, R.rtScene, f);
    src = R.rtScene;
  } else {
    R.clearTarget(R.rtAccum);
    for (let s = 0; s < subframes; s++) {
      const ts = t + ((s + 0.5) / subframes - 0.5) * (shutter / 60);
      D.render(ts, R.rtScene, f);
      R.copy(R.rtScene, R.rtAccum, 1 / subframes, true);
    }
    src = R.rtAccum;
  }
  R.finish(src, D.grade(t), f, true);
}

async function post(url, body) {
  const r = await fetch(url, { method: 'POST', body });
  if (!r.ok) throw new Error('post failed ' + url);
}

// Render a list of frames, streaming raw RGBA to the host.
window.runFrames = async (frames, opts = {}) => {
  const inflight = [];
  const t0 = performance.now();
  for (let k = 0; k < frames.length; k++) {
    const f = frames[k];
    renderFrame(f, opts);
    R.read(px);
    inflight.push(post(`/frame?i=${f}&k=${k}`, new Blob([px])));
    if (inflight.length >= 3) await inflight.shift();
    if (k % 60 === 0) post(`/log?msg=${encodeURIComponent(`frame ${f} (${k + 1}/${frames.length}) ${((performance.now() - t0) / (k + 1)).toFixed(1)} ms/f`)}`, '');
  }
  await Promise.all(inflight);
  return { ms: (performance.now() - t0) / frames.length };
};

window.runRange = (a, b, opts = {}) => {
  const fr = [];
  for (let f = a; f < b; f++) fr.push(f);
  return window.runFrames(fr, opts);
};

window.info = () => ({ W, H, frames: A.nframes, bpm: A.bpm });
window.ready = true;

