// Headless render host: serves the renderer, receives raw frames and hands them to ffmpeg.
//   node run.mjs stills --times 1.5,40.3 [--scale 0.5] [--sub 1] [--out ../stills] [--tag x]
//   node run.mjs sheet  --times ... --cols 4 --name sheet.png [--scale 0.5]
//   node run.mjs video  --from 0 --to 12287 --sub 3 --out ../out/video.mp4 [--scale 1] [--crf 16]
//   node run.mjs clip   --t0 40 --t1 48 --scale 0.5 --out ../out/clip.mp4   (with audio, for spot checks)
import { chromium } from '/Users/vojta/Dev/evangelist-exchange/node_modules/playwright/index.mjs';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const mode = argv[0];
const arg = (k, d) => { const i = argv.indexOf('--' + k); return i >= 0 ? argv[i + 1] : d; };
const scale = parseFloat(arg('scale', mode === 'video' ? '1' : '0.5'));
const W = Math.round(1920 * scale), H = Math.round(1080 * scale);
const sub = parseInt(arg('sub', '1'));
const port = 8900 + Math.floor(Math.random() * 90);

let frames = [];
if (arg('times')) frames = arg('times').split(',').map((s) => Math.round(parseFloat(s) * 60));
if (arg('frames')) frames = arg('frames').split(',').map((s) => parseInt(s));
if (mode === 'video') { for (let f = parseInt(arg('from', '0')); f < parseInt(arg('to', '12287')); f++) frames.push(f); }
if (mode === 'clip') {
  const a = Math.round(parseFloat(arg('t0')) * 60), b = Math.round(parseFloat(arg('t1')) * 60);
  const step = parseInt(arg('step', '1'));
  for (let f = a; f < b; f += step) frames.push(f);
}

const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.json': 'application/json', '.bin': 'application/octet-stream' };
let ff = null;
const pending = new Map();
let nextK = 0;
let written = 0;
let doneResolve;
const allDone = new Promise((r) => (doneResolve = r));
const outDir = path.resolve(ROOT, arg('out', '../stills'));

function startFfmpeg() {
  if (mode === 'video') {
    const out = path.resolve(ROOT, arg('out', '../out/video.mp4'));
    fs.mkdirSync(path.dirname(out), { recursive: true });
    const crf = arg('crf', '16');
    ff = spawn('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', '-f', 'rawvideo', '-pix_fmt', 'rgba', '-s', `${W}x${H}`, '-r', '60', '-i', '-',
      '-vf', 'scale=out_color_matrix=bt709:out_range=tv,format=yuv420p',
      '-c:v', 'libx264', '-preset', arg('preset', 'slow'), '-crf', crf, '-profile:v', 'high', '-tune', 'film',
      '-x264-params', 'aq-mode=3:aq-strength=0.9:deblock=-1,-1',
      '-colorspace', 'bt709', '-color_primaries', 'bt709', '-color_trc', 'bt709', '-color_range', 'tv',
      '-g', '120', '-bf', '3', out], { stdio: ['pipe', 'inherit', 'inherit'] });
  } else if (mode === 'clip') {
    const out = path.resolve(ROOT, arg('out', '../out/clip.mp4'));
    fs.mkdirSync(path.dirname(out), { recursive: true });
    const t0 = parseFloat(arg('t0')), t1 = parseFloat(arg('t1'));
    const step = parseInt(arg('step', '1'));
    ff = spawn('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', '-f', 'rawvideo', '-pix_fmt', 'rgba', '-s', `${W}x${H}`, '-r', String(60 / step), '-i', '-',
      '-ss', String(t0), '-t', String(t1 - t0), '-i', path.resolve(ROOT, '../song.wav'),
      '-map', '0:v', '-map', '1:a', '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '20', '-pix_fmt', 'yuv420p', '-c:a', 'aac', '-b:a', '192k', '-shortest', out], { stdio: ['pipe', 'inherit', 'inherit'] });
  }
}

function flushOrdered() {
  while (pending.has(nextK)) {
    const { buf, res } = pending.get(nextK);
    pending.delete(nextK);
    nextK++;
    const ok = ff.stdin.write(buf);
    written++;
    if (ok) res.end('ok'); else ff.stdin.once('drain', () => res.end('ok'));
    if (written === frames.length) { ff.stdin.end(); ff.on('close', () => doneResolve()); }
  }
}

const server = http.createServer((req, res) => {
  const u = new URL(req.url, 'http://x');
  if (req.method === 'POST' && u.pathname === '/frame') {
    const chunks = [];
    req.on('data', (d) => chunks.push(d));
    req.on('end', () => {
      const buf = Buffer.concat(chunks);
      const f = parseInt(u.searchParams.get('i')), k = parseInt(u.searchParams.get('k'));
      if (mode === 'video' || mode === 'clip') { pending.set(k, { buf, res }); flushOrdered(); return; }
      fs.mkdirSync(outDir, { recursive: true });
      const name = path.join(outDir, `${arg('tag', 'f')}_${String(f).padStart(5, '0')}.png`);
      const p = spawn('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', '-f', 'rawvideo', '-pix_fmt', 'rgba', '-s', `${W}x${H}`, '-i', '-', name]);
      p.stdin.end(buf);
      p.on('close', () => { written++; res.end('ok'); if (written === frames.length) doneResolve(); });
    });
    return;
  }
  if (req.method === 'POST' && u.pathname === '/log') { console.log('[page]', u.searchParams.get('msg')); res.end(); return; }
  let p = path.join(ROOT, decodeURIComponent(u.pathname));
  if (u.pathname === '/') p = path.join(ROOT, 'index.html');
  if (!p.startsWith(ROOT) || !fs.existsSync(p)) { res.statusCode = 404; res.end(); return; }
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('Content-Type', MIME[path.extname(p)] || 'application/octet-stream');
  fs.createReadStream(p).pipe(res);
}).listen(port);

startFfmpeg();
const browser = await chromium.launch({ channel: 'chrome', headless: true, args: ['--use-angle=metal', '--enable-gpu', '--ignore-gpu-blocklist', '--disable-gpu-watchdog', '--disable-renderer-backgrounding'] });
const page = await browser.newPage({ viewport: { width: 800, height: 600 } });
page.on('console', (m) => console.log('[console]', m.text()));
page.on('pageerror', (e) => console.log('[pageerror]', e.message));
const t0 = Date.now();
await page.goto(`http://127.0.0.1:${port}/?scale=${scale}`);
await page.waitForFunction(() => window.ready === true || window.loadError, null, { timeout: 120000, polling: 100 });
const r = await page.evaluate(({ frames, sub }) => window.runFrames(frames, { subframes: sub }), { frames, sub });
await allDone;
console.log(`rendered ${frames.length} frames, ${r.ms.toFixed(1)} ms/frame in page, wall ${((Date.now() - t0) / 1000).toFixed(1)} s`);
if (mode === 'sheet') {
  const cols = parseInt(arg('cols', '3'));
  const name = path.join(outDir, arg('name', 'sheet.png'));
  const files = frames.map((f) => path.join(outDir, `${arg('tag', 'f')}_${String(f).padStart(5, '0')}.png`));
  const inputs = files.flatMap((f) => ['-i', f]);
  const rows = Math.ceil(files.length / cols);
  const layoutStr = files.map((_, i) => `${(i % cols) * W}_${Math.floor(i / cols) * H}`).join('|');
  await new Promise((res) => {
    const p = spawn('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', ...inputs, '-filter_complex', `${files.map((_, i) => `[${i}:v]`).join('')}xstack=inputs=${files.length}:layout=${layoutStr}:fill=black`, name], { stdio: 'inherit' });
    p.on('close', res);
  });
  console.log('sheet', name, rows, 'rows');
}
await browser.close();
server.close();

