// TEMP test director to validate the engine look.
import { LineBatch } from './lines.js';
import { MeshBatch } from './renderer.js';
import { makeCam } from './camera.js';
import { layout } from './font.js';
import { PHOS, MINT, AMBER, VOID, CYAN } from './palette.js';
import { cmul, TAU, rng } from './math.js';

export class Director {
  constructor(R, A) { this.R = R; this.A = A; this.L = new LineBatch(); this.S = new LineBatch(); this.M = new MeshBatch(); }
  prepare() {}
  grade() { return { exposure: 1.0, bloomAmt: 0.7, ca: 0.003, vignette: 0.7, grain: 0.02 }; }
  render(t, rt) {
    const { R, A, L, S } = this;
    R.clearTarget(rt, [0.002, 0.008, 0.007]);
    const cam = makeCam([0, 2.2, 6.5], [0, 0, 0], { fov: 45, focus: 6.8, aperture: 0.06 });
    L.reset();
    // radar rings on a tilted disc
    for (let r = 1; r <= 4; r++) {
      const pts = [];
      for (let k = 0; k <= 256; k++) { const a = k / 256 * TAU; pts.push([Math.cos(a) * r * 0.8, 0, Math.sin(a) * r * 0.8]); }
      L.poly(pts, cmul(PHOS, 1.2), 1.6);
    }
    // sweep
    const sw = A.barPhase(t) * TAU;
    for (let k = 0; k < 40; k++) {
      const a = sw - k * 0.02;
      L.seg([0, 0, 0], [Math.cos(a) * 3.2, 0, Math.sin(a) * 3.2], cmul(PHOS, 0.05 * (1 - k / 40)), cmul(PHOS, 0.2 * (1 - k / 40)), 2);
    }
    // particles (bokeh test)
    const rnd = rng(7);
    L.style({ soft: 0.6 });
    for (let i = 0; i < 400; i++) {
      const p = [(rnd() - 0.5) * 20, (rnd() - 0.2) * 6, (rnd() - 0.8) * 20];
      L.dot(p, cmul(rnd() < 0.2 ? AMBER : MINT, 0.6), 2.5);
    }
    L.style({ soft: 0 });
    R.drawLines(L, cam);
    // title in screen space
    S.reset();
    const lay = layout('ARCADE RUSH');
    const size = 92, x0 = 960 - lay.width * size / 2, y0 = 540 + size / 2;
    S.style({ halo: 1 });
    for (const st of lay.strokes) {
      S.poly(st.pts.map((p) => [x0 + p[0] * size, y0 - p[1] * size, 0]), cmul(MINT, 1.6), 6);
    }
    const lay2 = layout('VOHO', { tracking: 0.9 });
    const s2 = 26, x2 = 960 - lay2.width * s2 / 2, y2 = 700;
    for (const st of lay2.strokes) S.poly(st.pts.map((p) => [x2 + p[0] * s2, y2 - p[1] * s2, 0]), cmul(AMBER, 1.4), 2.5);
    S.style({ halo: 0 });
    R.drawLines(S, null);
  }
}

