// Full-screen background: vertical gradient, horizon glow and a domain-warped "fluid" nebula.
import { GLSL_COMMON } from '../gl.js';

const FS = `#version 300 es
precision highp float;
in vec2 vUv;
uniform vec3 uTop, uBot, uGlow, uNebA, uNebB;
uniform float uHorizon, uGlowW, uNeb, uNebT, uNebScale, uNebWarp, uAspect, uRoll, uNebBias, uNebFlow;
uniform vec2 uNebCenter;
out vec4 o;
${GLSL_COMMON}
void main(){
  vec2 uv = vUv;
  vec2 c = (uv - .5) * vec2(uAspect, 1.);
  float cr = cos(uRoll), sr = sin(uRoll);
  c = mat2(cr, -sr, sr, cr) * c;
  float y = c.y + .5;
  vec3 col = mix(uBot, uTop, smoothstep(uHorizon - .25, uHorizon + .6, y));
  float hd = y - uHorizon;
  col += uGlow * exp(-abs(hd) / max(1e-3, uGlowW)) * (hd > 0. ? 1. : .55);
  if (uNeb > 0.) {
    vec2 p = (c - uNebCenter) * uNebScale;
    // radial flow option: streams outward from centre (hyperspace) when uNebFlow > 0
    float r = length(p), a = atan(p.y, p.x);
    vec2 q = mix(p, vec2(a * 1.2, log(r + .05) * 1.4 - uNebT * 1.3), uNebFlow);
    vec2 w = vec2(fbm(q + vec2(0., uNebT * .31)), fbm(q + vec2(5.2, 1.3) - uNebT * .23));
    vec2 w2 = vec2(fbm(q + w * uNebWarp + vec2(1.7, 9.2) + uNebT * .12), fbm(q + w * uNebWarp + vec2(8.3, 2.8) - uNebT * .17));
    float n = fbm(q + w2 * uNebWarp);
    float m = smoothstep(uNebBias, 1., n);
    vec3 nc = mix(uNebA, uNebB, smoothstep(.2, .9, w2.x));
    col += nc * m * m * uNeb;
  }
  o = vec4(col, 1.);
}`;

export function sky(R, p = {}) {
  R.fx('sky', FS, {
    uTop: p.top || [0.0, 0.004, 0.004], uBot: p.bot || [0.0, 0.0, 0.0], uGlow: p.glow || [0, 0, 0],
    uHorizon: p.horizon ?? 0.5, uGlowW: p.glowW ?? 0.05, uNeb: p.neb ?? 0, uNebA: p.nebA || [0, 0.1, 0.06], uNebB: p.nebB || [0.1, 0.05, 0],
    uNebT: p.nebT ?? 0, uNebScale: p.nebScale ?? 2.2, uNebWarp: p.nebWarp ?? 2.0, uAspect: R.w / R.h, uRoll: p.roll ?? 0,
    uNebBias: p.nebBias ?? 0.35, uNebFlow: p.nebFlow ?? 0, uNebCenter: p.nebCenter || [0, 0],
  }, { blend: p.blend || 'none' });
}

