// The Reticle: holographic radar disc. Sweep = one revolution per bar; the disc surface is a
// polar spectrogram painted by the sweep (angle = time within the bar, radius = frequency).
import { TAU, cmul, clamp, cmix } from '../math.js';
import { PHOS, MINT, AMBER } from '../palette.js';

const scratch = new Float32Array(64);

export function radarPoint(c, r, a, y = 0) { return [c[0] + Math.cos(a) * r, c[1] + y, c[2] + Math.sin(a) * r]; }

export function sweepAngle(A, t) { return -A.barPhase(t) * TAU - Math.PI / 2; }

export function drawRadar(L, M, A, t, o = {}) {
  const c = o.c || [0, 0, 0];
  const R = o.R ?? 3.2;
  const gain = o.gain ?? 1;
  const col = o.col || PHOS, core = o.core || MINT, acc = o.acc || AMBER;
  const reveal = o.reveal ?? 1;          // 0..1 draw-on of structure
  const specAmt = o.specAmt ?? 1;
  const scopeAmt = o.scopeAmt ?? 1;
  const sweepAmt = o.sweepAmt ?? 1;
  const ticksAmt = o.ticksAmt ?? 1;
  const tickReveal = o.tickReveal ?? 1;  // cardinal ticks 0..4
  const lw = o.lw ?? 1.6;
  const ringY = o.ringY || ((k) => 0);  // extrusion (funnel) per ring index
  const sw = sweepAngle(A, t);
  const sub = A.env('sub', t);

  // concentric rings (written on in sequence)
  const rings = o.rings || [0.25, 0.5, 0.75, 1.0];
  rings.forEach((rr, k) => {
    const u = clamp(reveal * rings.length - k);
    if (u <= 0) return;
    const pts = [];
    const n = 200;
    const y = ringY(k);
    for (let i = 0; i <= n; i++) pts.push(radarPoint(c, R * rr, sw + (i / n) * TAU, y));
    const bright = (k === rings.length - 1 ? 1.25 : 0.7) * gain;
    L.polyRange(pts, 0, u, cmul(col, bright), k === rings.length - 1 ? lw * 1.4 : lw, false, cmul(core, 3 * gain));
  });

  // crosshair diameters (dim, broken at centre)
  if (reveal > 0.5) {
    const k = clamp((reveal - 0.5) * 2) * gain * 0.35;
    for (let q = 0; q < 4; q++) {
      const a = q * Math.PI / 2;
      L.seg(radarPoint(c, R * 0.08, a), radarPoint(c, R * 0.98, a), cmul(col, k * 0.4), cmul(col, k), 1.1, 1.1);
    }
  }

  // bezel ticks: 64 sixteenth ticks flash as the sweep passes (a 16th-note clock), 4 cardinal ticks
  if (ticksAmt > 0) {
    for (let i = 0; i < 64; i++) {
      const a = -Math.PI / 2 - (i / 64) * TAU;
      const major = i % 16 === 0, mid = i % 4 === 0;
      if (major && i / 16 >= tickReveal) continue;
      const len = major ? 0.16 : mid ? 0.08 : 0.04;
      let d = ((a - sw) % TAU + TAU) % TAU; // angle since sweep passed (sweep moves negative)
      d = TAU - d; if (d >= TAU) d -= TAU;
      const age = d / TAU;
      const flash = Math.exp(-age * 18);
      const b = (major ? 1.2 : mid ? 0.55 : 0.28) * ticksAmt * gain * (0.5 + 1.8 * flash);
      const r0 = R * (1.03), r1 = R * (1.03 + len);
      L.seg(radarPoint(c, r0, a), radarPoint(c, r1, a), cmul(major ? core : col, b), cmul(col, b * 0.6), major ? 2.2 : 1.4, major ? 2.2 : 1.4);
    }
  }

  // sweep beam + afterglow wedge (mesh, additive)
  if (sweepAmt > 0) {
    const tip = radarPoint(c, R, sw);
    L.seg(c, tip, cmul(core, 0.6 * sweepAmt * gain), cmul(core, 2.2 * sweepAmt * gain), 1.5, 2.5);
    const n = 48, span = 1.3;
    for (let i = 0; i < n; i++) {
      const a0 = sw + (i / n) * span, a1 = sw + ((i + 1) / n) * span;
      const k0 = Math.pow(1 - i / n, 2.2) * 0.16 * sweepAmt * gain, k1 = Math.pow(1 - (i + 1) / n, 2.2) * 0.16 * sweepAmt * gain;
      M.v(c, cmul(col, 0), 1); M.v(radarPoint(c, R, a0), cmul(col, k0), 1); M.v(radarPoint(c, R, a1), cmul(col, k1), 1);
    }
  }

  // polar spectrogram: a persistence screen written by the sweep
  if (specAmt > 0) {
    const NA = 120, NR = 20;
    const bar = A.bar;
    for (let j = 0; j < NA; j++) {
      const a = -Math.PI / 2 - (j / NA) * TAU;
      let d = ((sw - a) % TAU + TAU) % TAU;
      const age = (d / TAU) * bar;
      const ts = t - age;
      if (ts < 0) continue;
      const pers = Math.exp(-age / (0.5 * bar)) + 1.6 * Math.exp(-age / 0.05);
      const sp = A.spec(ts, scratch);
      for (let k = 0; k < NR; k++) {
        const b0 = k * 3;
        const v = Math.max(sp[b0], sp[b0 + 1], sp[b0 + 2]);
        const e = Math.pow(v, 2.4) * pers * specAmt * gain;
        if (e < 0.015) continue;
        const r = R * (0.12 + 0.8 * (k + 0.5) / NR);
        const p = radarPoint(c, r, a);
        const tang = [-Math.sin(a), 0, Math.cos(a)];
        const s = R * 0.8 / NR * (0.25 + 0.5 * v);
        L.ww = s;
        const cc = k < 3 ? cmix(acc, core, v * 0.5) : cmix(col, core, v * v);
        L.seg([p[0] - tang[0] * s * 0.5, p[1], p[2] - tang[2] * s * 0.5], [p[0] + tang[0] * s * 0.5, p[1], p[2] + tang[2] * s * 0.5], cmul(cc, e * 1.4), cmul(cc, e * 1.4), 0, 0, 0, 0);
        L.ww = 0;
      }
    }
  }

  // circular oscilloscope on the rim (the actual waveform)
  if (scopeAmt > 0) {
    const n = 420, span = 0.045;
    const pts = [];
    for (let i = 0; i <= n; i++) {
      const u = i / n;
      const s = A.sample(t - span + u * span);
      const m = (s[0] + s[1]) * 0.5;
      const a = -Math.PI / 2 - u * TAU;
      pts.push(radarPoint(c, R * (1.2 + m * 0.22 * scopeAmt), a));
    }
    L.poly(pts, cmul(acc, 0.8 * scopeAmt * gain * (0.6 + sub)), 1.4, false);
  }

  // shockwaves
  if (o.shocks) for (const s of o.shocks) {
    const age = t - s.t;
    if (age < 0 || age > 1.2) continue;
    const r = R * (0.05 + 1.5 * (1 - Math.exp(-age * 3.2)));
    const k = s.s * Math.exp(-age * 3.5) * gain;
    const pts = [];
    for (let i = 0; i <= 160; i++) pts.push(radarPoint(c, r, (i / 160) * TAU));
    L.poly(pts, cmul(core, 2.2 * k), 2.5 + 4 * k);
  }
}

