    const k = s.s * Math.exp(-age * 3.5) * gain;
    const pts = [];
    for (let i = 0; i <= 160; i++) pts.push(radarPoint(c, r, (i / 160) * TAU));
    L.poly(pts, cmul(core, 2.2 * k), 2.5 + 4 * k);
  }
}

