// Kinetic typography built on the stroke font.
import { layout } from '../font.js';

// map(x, y, gi) -> point, x/y in cap-height units relative to the aligned anchor.
export function drawText(L, str, o = {}) {
  const lay = layout(str, { tracking: o.tracking ?? 0.38, radius: o.radius });
  const ax = o.align === 'left' ? 0 : o.align === 'right' ? -lay.width : -lay.width / 2;
  const ay = o.valign === 'baseline' ? 0 : o.valign === 'top' ? -1 : -0.5;
  const w = o.w ?? 2;
  const nStroke = lay.strokes.length;
  lay.strokes.forEach((st, si) => {
    const gi = st.glyph;
    let u0 = 0, u1 = 1;
    if (o.reveal) {
      const r = o.reveal(si, gi, st, nStroke, lay.glyphs.length);
      if (Array.isArray(r)) { u0 = r[0]; u1 = r[1]; } else u1 = r;
    }
    if (u1 <= u0 || u1 <= 0) return;
    const col = o.colorFn ? o.colorFn(si, gi) : o.color;
    if (!col) return;
    const off = o.offset ? o.offset(si, gi) : null;
    const pts = st.pts.map((p) => {
      const x = p[0] + ax + (off ? off[0] : 0), y = p[1] + ay + (off ? off[1] : 0);
      return o.map(x, y, gi, si);
    });
    const ww = typeof w === 'function' ? w(si, gi) : w;
    if (u0 <= 0 && u1 >= 1) L.poly(pts, col, ww, false);
    else L.polyRange(pts, Math.max(0, u0), Math.min(1, u1), col, ww, false, o.head ? o.head : null);
  });
  return lay;
}

export function textWidth(str, tracking = 0.38) { return layout(str, { tracking }).width; }

// screen-space helper: centre (cx, cy) in 1080p pixels, size = cap height px
export const screenMap = (cx, cy, size) => (x, y) => [cx + x * size, cy - y * size, 0];

// world-space helper on a plane: origin + x*right + y*up
export const planeMap = (o, right, up, size) => (x, y) => [
  o[0] + (right[0] * x + up[0] * y) * size,
  o[1] + (right[1] * x + up[1] * y) * size,
  o[2] + (right[2] * x + up[2] * y) * size,
];

