// Timeline helpers shared by scenes.
import { clamp } from '../math.js';

// Integrated distance for a speed profile; rings/objects laid on musical times via dist(t_k)
// always pass the camera exactly at t_k regardless of acceleration.
export class Path {
  constructor(speedFn, t0, t1, dt = 1 / 480) {
    this.t0 = t0; this.dt = dt;
    const n = Math.ceil((t1 - t0) / dt) + 2;
    this.d = new Float64Array(n);
    let acc = 0;
    for (let i = 1; i < n; i++) {
      const ta = t0 + (i - 1) * dt, tb = t0 + i * dt;
      acc += (speedFn(ta) + 4 * speedFn((ta + tb) / 2) + speedFn(tb)) / 6 * dt;
      this.d[i] = acc;
    }
    this.speed = speedFn;
  }
  at(t) {
    const x = (t - this.t0) / this.dt;
    if (x <= 0) return this.d[0] + (t - this.t0) * this.speed(this.t0);
    const i = Math.floor(x);
    if (i >= this.d.length - 1) return this.d[this.d.length - 1] + (x - (this.d.length - 1)) * this.dt * this.speed(this.t0 + (this.d.length - 1) * this.dt);
    const f = x - i;
    return this.d[i] * (1 - f) + this.d[i + 1] * f;
  }
}

// piecewise keyframes: [[t, v], ...] with ease per segment
export function keys(t, ks, ease = (x) => x * x * (3 - 2 * x)) {
  if (t <= ks[0][0]) return ks[0][1];
  for (let i = 0; i < ks.length - 1; i++) {
    const [ta, va] = ks[i], [tb, vb] = ks[i + 1];
    if (t <= tb) {
      const u = ease(clamp((t - ta) / (tb - ta)));
      if (Array.isArray(va)) return va.map((a, j) => a + (vb[j] - a) * u);
      return va + (vb - va) * u;
    }
  }
  return ks[ks.length - 1][1];
}

export const win = (t, a, b) => t >= a && t < b;
export const prog = (t, a, b) => clamp((t - a) / (b - a));
// fade in over [a, a+fi], out over [b-fo, b]
export const env = (t, a, b, fi = 0.3, fo = 0.3) => Math.min(clamp((t - a) / fi), clamp((b - t) / fo));

