const wrap = (x, a) => ((x % a) + a) % a;

// Floating dust motes in a box around `c`; drift is a velocity (units/s). square=true -> pixel squares
export function dust(L, t, o) {
  const { c = [0, 0, 0], ext = [10, 6, 10], n = 300, seed = 1, drift = [0, 0.1, 0], col, size = 2, sparkle = null, square = false, gain = 1, ww = 0 } = o;
  for (let i = 0; i < n; i++) {
    const hx = hash2(i, seed), hy = hash2(i, seed + 1), hz = hash2(i, seed + 2), hs = hash2(i, seed + 3);
    const sp = 0.5 + hs;
    const p = [
      c[0] + wrap(hx * ext[0] + drift[0] * t * sp, ext[0]) - ext[0] / 2,
      c[1] + wrap(hy * ext[1] + drift[1] * t * sp, ext[1]) - ext[1] / 2,
      c[2] + wrap(hz * ext[2] + drift[2] * t * sp, ext[2]) - ext[2] / 2,
    ];
    // fade near the wrap boundaries so particles never pop
    const edge = Math.min(
      edgeFade(p[0] - c[0], ext[0]), edgeFade(p[1] - c[1], ext[1]), edgeFade(p[2] - c[2], ext[2]));
    let k = (0.35 + 0.65 * hash2(i, seed + 4)) * edge * gain;
    if (sparkle) k *= sparkle(i, hs);
    if (k < 0.004) continue;
    const cc = typeof col === 'function' ? col(i, hs) : col;
    const s = size * (0.6 + 0.8 * hash2(i, seed + 5));
    if (square) {
      L.ww = ww * (0.6 + 0.8 * hash2(i, seed + 5));
      const h = L.ww * 0.5;
      L.seg([p[0] - h, p[1], p[2]], [p[0] + h, p[1], p[2]], cmul(cc, k), cmul(cc, k), s * 0.0, s * 0.0, 0, 0);
      L.ww = 0;
    } else {
      L.ww = ww;
      L.dot(p, cmul(cc, k), s);
      L.ww = 0;
    }
  }
}

function edgeFade(x, e) { const d = e / 2 - Math.abs(x); return Math.min(1, Math.max(0, d / (e * 0.12))); }

// Stars on a big sphere shell (direction only; follow the camera)
export function stars(L, camEye, o) {
  const { n = 800, r = 400, seed = 9, col, size = 1.6, gain = 1, twinkle = null } = o;
  for (let i = 0; i < n; i++) {
    const u = hash2(i, seed) * 2 - 1, th = hash2(i, seed + 1) * TAU;
    const s = Math.sqrt(1 - u * u);
    const d = [s * Math.cos(th), u, s * Math.sin(th)];
    const p = [camEye[0] + d[0] * r, camEye[1] + d[1] * r, camEye[2] + d[2] * r];
    let k = Math.pow(hash2(i, seed + 2), 3) * 1.4 + 0.08;
    if (twinkle) k *= twinkle(i);
    const cc = typeof col === 'function' ? col(i) : col;
    L.dot(p, cmul(cc, k * gain), size * (0.7 + hash2(i, seed + 3)));
  }
}

// Radial burst from origin at time t0: particles fly out and fade.
export function burst(L, t, t0, o) {
  const age = t - t0;
  const { c = [0, 0, 0], n = 200, seed = 3, speed = 6, life = 1.2, col, size = 2.5, gain = 1, flat = null, drag = 2.2, square = false } = o;
  if (age < 0 || age > life) return;
  for (let i = 0; i < n; i++) {
    let d;
    if (flat) { const a = hash2(i, seed) * TAU; d = [Math.cos(a) * flat[0], 0, Math.sin(a) * flat[1]]; d[1] = (hash2(i, seed + 7) - 0.5) * 0.15; }
    else {
      const u = hash2(i, seed) * 2 - 1, th = hash2(i, seed + 1) * TAU, s = Math.sqrt(1 - u * u);
      d = [s * Math.cos(th), u, s * Math.sin(th)];
    }
    const sp = speed * (0.3 + 0.7 * hash2(i, seed + 2));
    const dist = sp * (1 - Math.exp(-age * drag)) / drag;
    const p = [c[0] + d[0] * dist, c[1] + d[1] * dist, c[2] + d[2] * dist];
    const k = Math.pow(1 - age / life, 1.6) * gain * (0.4 + 0.6 * hash2(i, seed + 3));
    const cc = typeof col === 'function' ? col(i) : col;
    // motion streak: previous position a few ms back
    const age2 = Math.max(0, age - 0.035);
    const dist2 = sp * (1 - Math.exp(-age2 * drag)) / drag;
    const q = [c[0] + d[0] * dist2, c[1] + d[1] * dist2, c[2] + d[2] * dist2];
    L.seg(q, p, cmul(cc, k * 0.3), cmul(cc, k), size * 0.6, size);
  }
}

