// 0:00 - 0:22.46  Power-on + attract mode. CRT dot -> line rolls into the reticle -> radar ->
// holographic title -> title un-writes -> rings extrude into a funnel -> dive.
import { makeCam } from '../camera.js';
import { drawRadar, radarPoint } from '../comp/radar.js';
import { drawText, planeMap } from '../comp/text.js';
import { dust, stars } from '../comp/particles.js';
import { sky } from '../comp/sky.js';
import { keys, prog } from '../comp/util.js';
import { PHOS, MINT, AMBER, CYAN } from '../palette.js';
import { cmul, cmix, clamp, easeOutExpo, easeInOutCubic, easeInCubic, easeOutCubic, smooth, TAU, hash2, lerp, noise1, fract } from '../math.js';

const T_FIRST = 0.111;
const T_SUBIN = 4.298;

export const TITLE_START = 5.80;     // bar 2 beat 3 - one glyph per 8th note
export const VOHO_START = 9.134;     // bar 4 - one letter per beat

export function introCamera(A, t) {
  // top-down during boot, tilts into a 3/4 orbit on the sub entrance, rises top-down again over bar 9, dives on the 22.01 impact
  const bar8 = A.barT(8), bar9 = A.barT(9), dive0 = 22.01, dive1 = A.barT(10);
  const tilt = easeInOutCubic(prog(t, T_SUBIN, T_SUBIN + 2.6));
  const phi = lerp(-0.34, 0.22, smooth(T_SUBIN, bar8 + 1, t)) + noise1(t * 0.13, 3) * 0.03;
  const orbitR = lerp(8.4, 6.9, smooth(T_SUBIN, bar8, t));
  const orbitEye = [Math.sin(phi) * orbitR, lerp(2.2, 2.8, smooth(6, bar8, t)) + noise1(t * 0.2, 5) * 0.06, Math.cos(phi) * orbitR];
  const topEye = [0, 10.5, 0.001];
  let eye = [lerp(topEye[0], orbitEye[0], tilt), lerp(topEye[1], orbitEye[1], tilt), lerp(topEye[2], orbitEye[2], tilt)];
  let target = [0, lerp(0, 0.75, tilt), 0];
  let fov = lerp(36, 40, tilt);
  // rise back to top-down over bar 9 (the funnel forms)
  const up = easeInOutCubic(prog(t, bar8 + A.bar * 0.5, dive0));
  if (up > 0) {
    const e2 = [0, 8.5, 0.001];
    eye = [lerp(eye[0], e2[0], up), lerp(eye[1], e2[1], up), lerp(eye[2], e2[2], up)];
    target = [0, lerp(target[1], -4, up), 0];
    fov = lerp(fov, 48, up);
  }
  // dive: 22.01 -> bar 10, accelerate down the axis
  const dv = prog(t, dive0, dive1);
  if (dv > 0) {
    const y = lerp(8.5, 0.0, easeInCubic(dv));
    eye = [0, y, 0.001];
    target = [0, y - 10, 0];
    fov = lerp(48, 70, easeInCubic(dv));
  }
  let focus = Math.hypot(eye[0] - 0, eye[1] - 1.2, eye[2] - 0);
  return makeCam(eye, target, { fov, focus, aperture: 0.05 * tilt * (1 - up), roll: up > 0 ? 0 : noise1(t * 0.11, 8) * 0.02 });
}

export function drawIntro(ctx, t) {
  const { R, A, L, S, M } = ctx;
  const bar = A.bar;
  const loud = A.env('loudSlow', t);
  const fadeIn = clamp(smooth(T_FIRST, 3.8, t) * 0.8 + loud * 0.4);
  const cam = introCamera(A, t);
  const bar8 = A.barT(8), bar9 = A.barT(9);

  // ------------------------------------------------ background
  const tilt = easeInOutCubic(prog(t, T_SUBIN, T_SUBIN + 2.6));
  sky(R, {
    top: cmul([0.0, 0.012, 0.01], fadeIn), bot: [0.0, 0.0, 0.0], horizon: 0.35, glow: cmul(PHOS, 0.004 * tilt), glowW: 0.2,
    neb: 0.10 * tilt * (0.6 + A.env('midSlow', t)), nebA: [0.0, 0.035, 0.026], nebB: [0.03, 0.02, 0.0], nebT: t * 0.07, nebScale: 1.4, nebBias: 0.4,
  });

  L.reset(); M.reset(); S.reset();

  // ------------------------------------------------ boot: CRT dot -> line -> rolls up into the outer ring
  const R0 = 3.2;
  const lineIn = easeOutExpo(prog(t, T_FIRST, 0.75));
  const roll = easeInOutCubic(prog(t, 0.75, 1.7));
  if (t >= T_FIRST && roll < 1) {
    const n = 160;
    const pts = [];
    const halfLen = R0 * Math.PI * lineIn;
    for (let i = 0; i <= n; i++) {
      const u = i / n * 2 - 1;
      const lin = [u * halfLen, 0, 0];
      const a = Math.PI / 2 + u * Math.PI;
      const circ = [Math.cos(a) * R0, 0, Math.sin(a) * R0 - 0];
      // roll: the line bends around to meet itself at the top
      pts.push([lerp(lin[0], -circ[0], roll), 0, lerp(lin[2], circ[2] + R0, roll) - R0 * roll]);
    }
