// 0:22.46 - 0:40.23  Intro B: dive down the reticle into a Tempest-style vector tunnel.
// One ring per sixteenth note, laid on the path so each ring passes the camera exactly on its 16th.
// Bars 16-17: sub-bass drops out, highs rise -> tunnel narrows, accelerates and implodes on the drop.
import { makeCam } from '../camera.js';
import { Path, prog } from '../comp/util.js';
import { sky } from '../comp/sky.js';
import { stars } from '../comp/particles.js';
import { drawText, screenMap } from '../comp/text.js';
import { PHOS, MINT, AMBER, CYAN } from '../palette.js';
import { cmul, cmix, clamp, smooth, lerp, TAU, hash2, easeInCubic, easeInExpo, noise1, easeOutCubic } from '../math.js';

let path = null;
let T0, T_BUILD, T_DROP, T_IMP;

function setup(A) {
  if (path) return;
  T0 = A.barT(10); T_BUILD = A.barT(16); T_DROP = A.barT(18); T_IMP = T_DROP - 0.42;
  const base = 4.2;
  path = new Path((t) => {
    let v = base + 30 * Math.exp(-Math.max(0, t - T0) / 0.22);
    if (t > T_BUILD) v = base * Math.exp(Math.log(10) * Math.pow(prog(t, T_BUILD, T_DROP), 1.7));
    return v;
  }, T0 - 1, T_DROP + 1);
}

export const tunnelDist = (A, t) => { setup(A); return path.at(t); };

// radius / shape as a function of *ring time* (the geometry is static in space)
function ringRadius(A, tk) {
  let r = 1.35;
  r = lerp(r, 0.55, smooth(T_BUILD, T_DROP - 0.3, tk));
  return r;
}
function ringShape(A, tk) { return smooth(A.barT(14), A.barT(14) + A.bar, tk) * (1 - smooth(A.barT(16), A.barT(16) + A.bar, tk) * 0.6); }
function ringTwist(A, tk) { return tk * 0.18 + smooth(T_BUILD, T_DROP, tk) * 2.5; }

function polyVert(i, n, r, shape, twist) {
  const a = (i / n) * TAU + twist;
  let x = Math.cos(a), y = Math.sin(a);
  // circle -> square (pixel motif)
  const m = Math.max(Math.abs(x), Math.abs(y));
  x = lerp(x, x / m * 0.9, shape); y = lerp(y, y / m * 0.9, shape);
  return [x * r, y * r];
}

export function tunnelCamera(A, t) {
  setup(A);
  const d = path.at(t);
  const kick = A.pulse('kick', t, 0.12);
  const build = smooth(T_BUILD, T_DROP, t);
  const roll = t * 0.12 + easeInCubic(build) * 2.2 + noise1(t * 0.3, 4) * 0.05;
  const eye = [0, -d, 0.0];
  const fov = 70 + build * 22 + kick * 5 * build;
  const cam = makeCam(eye, [Math.sin(t * 0.4) * 0.05, -d - 10, 0.001], { fov, near: 0.02, roll });
  return cam;
}

export function drawTunnel(ctx, t) {
  const { R, A, L, S, M } = ctx;
  setup(A);
  const cam = tunnelCamera(A, t);
  const d = path.at(t);
  const build = smooth(T_BUILD, T_DROP, t);
  const imp = easeInExpo(prog(t, T_IMP, T_DROP - 0.03));
  const loud = A.env('loud', t), mid = A.env('mid', t), high = A.env('high', t), sub = A.env('sub', t);

  sky(R, { top: [0, 0.006, 0.005], bot: [0, 0.006, 0.005], neb: 0.25 * (1 - imp), nebA: [0.0, 0.05, 0.035], nebB: [0.04, 0.02, 0.0], nebT: t * 0.2 + d * 0.02, nebScale: 1.2, nebFlow: 1, nebBias: 0.45 });

  L.reset(); M.reset(); S.reset();
  const s16 = A.period / 4;
  const kNow = Math.floor((t - A.beat0) / s16);
  const N = 16;
  const sq = (1 - imp);
  // rings ahead
  const rings = [];
  for (let k = kNow - 2; k < kNow + 140; k++) {
    const tk = A.beat0 + k * s16;
    if (tk < T0 - 0.3) continue;
    const dk = path.at(tk) - d;
    if (dk < -0.5) continue;
    if (dk > 70) break;
    rings.push({ k, tk, dk });
  }
  const fog = (dk) => Math.exp(-dk / (18 + build * 30)) * clamp((dk + 0.5) / 1.5);
  const verts = rings.map((rg) => {
    const r = ringRadius(A, rg.tk) * sq;
    const shp = ringShape(A, rg.tk), tw = ringTwist(A, rg.tk);
    const out = [];
    for (let i = 0; i <= N; i++) { const v = polyVert(i % N, N, r, shp, tw); out.push([v[0], -d - rg.dk, v[1]]); }
    return out;
  });
  rings.forEach((rg, ri) => {
    const f = fog(rg.dk);
    if (f < 0.003) return;
    const down = rg.k % 16 === 0, beat = rg.k % 4 === 0;
    const note = A.env('mid', rg.tk), sb = A.env('sub', rg.tk);
    let k = (down ? 1.6 : beat ? 0.75 : 0.28) * (0.55 + 0.9 * note + 0.6 * build);
    const col = cmix(cmix(PHOS, AMBER, clamp(sb * 1.2 - 0.2) * (1 - build)), MINT, build * 0.7 + (down ? 0.3 : 0));
    L.poly(verts[ri], cmul(col, k * f * (1 + 0.5 * loud)), down ? 2.6 : beat ? 1.8 : 1.1, false);
    if (down) {
      // reticle ticks on bar lines
      for (let q = 0; q < 4; q++) {
        const a = q * Math.PI / 2 + ringTwist(A, rg.tk);
        const r = ringRadius(A, rg.tk) * sq;
        L.seg([Math.cos(a) * r * 1.05, -d - rg.dk, Math.sin(a) * r * 1.05], [Math.cos(a) * r * 1.35, -d - rg.dk, Math.sin(a) * r * 1.35], cmul(MINT, 2 * f), cmul(PHOS, 0.5 * f), 2.5, 1.5);
      }
    }
  });
  // lanes
  for (let i = 0; i < N; i++) {
    const pts = [], cols = [];
    for (let ri = 0; ri < rings.length; ri++) pts.push(verts[ri][i]);
    if (pts.length < 2) continue;
    const laneK = (i % 4 === 0 ? 0.55 : 0.22) * (0.6 + build);
